var e=JSON.parse(`[{"id":"09-a1b2c3d4","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Migration strategies","difficulty":"medium","question":"A company is evaluating 200 on-premises applications for cloud migration. Some applications are outdated and no longer business-critical. Others run on licensed software with a newer SaaS alternative. A third group runs on custom code that would benefit from being rebuilt as microservices. Which combination of 6R strategies applies to each group?","options":{"A":"Outdated apps → Refactor; licensed apps → Replatform; custom code → Rehost","B":"Outdated apps → Retire; licensed apps → Repurchase; custom code → Refactor","C":"Outdated apps → Retain; licensed apps → Retire; custom code → Replatform","D":"Outdated apps → Repurchase; licensed apps → Rehost; custom code → Retain"},"correct":"B","explanation":"The 6R migration strategies: Retire — decommission applications no longer needed (outdated, non-critical apps save maintenance costs). Repurchase — move to a SaaS product (e.g., Salesforce, Workday) instead of running licensed on-premises software. Refactor/Re-architect — redesign the application to use cloud-native services like microservices on ECS/Lambda — highest business value but greatest effort. Each R strategy has a specific profile of effort, cost, and transformation depth.","distractors":{"A":"Outdated apps should be Retired (not Refactored), which wastes effort on applications that should be decommissioned.","C":"Outdated apps should be Retired, not Retained — Retain means keeping them on-premises temporarily, not eliminating them.","D":"Repurchase means replacing with a SaaS product — it applies to apps with a licensed software alternative, not arbitrary outdated applications."},"source_url":"https://docs.aws.amazon.com/prescriptive-guidance/latest/large-migration-guide/overview.html","tags":["migration","6r","retire","repurchase","refactor","strategy"],"verified":true},{"id":"09-a1b2c3d5","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Migration strategies","difficulty":"easy","question":"A company must migrate 500 on-premises VMs to AWS within 3 months with minimal changes. The applications are running on VMware vSphere and must maintain the same OS, configurations, and dependencies. Which AWS service automates this lift-and-shift migration?","options":{"A":"AWS Database Migration Service (DMS)","B":"AWS Application Migration Service (AWS MGN)","C":"AWS DataSync","D":"AWS Schema Conversion Tool"},"correct":"B","explanation":"AWS Application Migration Service (AWS MGN, formerly CloudEndure Migration) is the primary AWS service for lift-and-shift (Rehost) server migrations. It continuously replicates source servers (physical, virtual, or cloud) to AWS, then allows non-disruptive testing before final cutover. It supports Windows and Linux VMs from VMware, Hyper-V, and other environments, cutting over to EC2 instances with identical configurations in minutes.","distractors":{"A":"AWS DMS migrates database workloads — it does not migrate full VMs or application servers including OS and configurations.","C":"AWS DataSync transfers files between on-premises storage and AWS storage services (S3, EFS, FSx) — it moves data files, not running VMs or their configurations.","D":"AWS Schema Conversion Tool converts database schemas from one engine to another (e.g., Oracle to Aurora) — it is for database migrations, not VM migrations."},"source_url":"https://docs.aws.amazon.com/mgn/latest/ug/what-is-application-migration-service.html","tags":["mgn","migration","lift-and-shift","rehost","vm"],"verified":true},{"id":"09-a1b2c3d6","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Database Migration Service","difficulty":"medium","question":"A company is migrating an Oracle database to Amazon Aurora PostgreSQL. The Oracle database uses Oracle-specific stored procedures and custom data types. What is the correct two-step migration approach?","options":{"A":"Use AWS DMS Full Load only — DMS converts Oracle syntax to PostgreSQL automatically","B":"Use AWS Schema Conversion Tool (SCT) to convert the schema and stored procedures, then use AWS DMS for the data migration","C":"Use AWS DataSync to copy the Oracle data files to S3, then import into Aurora PostgreSQL","D":"Use AWS Glue ETL to transform Oracle data into PostgreSQL-compatible format"},"correct":"B","explanation":"Heterogeneous database migrations (different engine types, e.g., Oracle to PostgreSQL) require two tools: (1) AWS Schema Conversion Tool (SCT) — analyzes the Oracle schema and stored procedures, converts them to PostgreSQL equivalents, and flags items requiring manual review (e.g., Oracle-specific syntax). (2) AWS DMS — migrates the actual data from Oracle to Aurora PostgreSQL, supporting both full load (initial migration) and CDC (ongoing replication) during cutover. This is the standard AWS heterogeneous migration pattern.","distractors":{"A":"AWS DMS does not automatically convert Oracle SQL syntax, stored procedures, or data types to PostgreSQL — that is SCT's job. DMS handles data movement, not schema conversion.","C":"DataSync copies files (NFS, SMB, S3, EFS) — it cannot read Oracle database files directly or import data into Aurora PostgreSQL.","D":"AWS Glue is an ETL service for data transformation in analytics pipelines — it is not designed for database engine migrations and does not handle Oracle stored procedure conversion."},"source_url":"https://docs.aws.amazon.com/SchemaConversionTool/latest/userguide/CHAP_Welcome.html","tags":["dms","sct","oracle","aurora","heterogeneous-migration"],"verified":true},{"id":"09-a1b2c3d7","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Database Migration Service","difficulty":"medium","question":"A company wants to migrate a production MySQL database to RDS for MySQL with zero downtime. The database is 2 TB. Which AWS DMS task type enables migration while the source database continues serving production traffic?","options":{"A":"Full Load only — DMS copies all data then terminates","B":"CDC (Change Data Capture) only — DMS only replicates changes after a specific timestamp","C":"Full Load + CDC — DMS performs initial full copy then continuously replicates changes until cutover","D":"DMS Snapshot restore — creates an RDS snapshot from the on-premises database"},"correct":"C","explanation":"'Full Load + CDC' is the standard zero-downtime migration task type. Phase 1 (Full Load): DMS copies all existing data from MySQL to RDS. The source database continues serving traffic throughout. Phase 2 (CDC): After full load completes, DMS switches to Change Data Capture mode — replicating every INSERT/UPDATE/DELETE from the source binary log in near-real-time. When replication lag reaches near-zero, the team cuts over (update app connection strings to RDS) with minimal downtime.","distractors":{"A":"Full Load only stops replicating changes after the initial copy — any changes made during the migration are lost. This requires downtime during the full load, which may take hours for a 2 TB database.","B":"CDC-only starts replication from a point in time — you still need to provision the initial data load separately (e.g., via mysqldump), adding complexity and requiring downtime for the initial seed.","D":"DMS Snapshot Restore is not a DMS feature — RDS native snapshot restore from on-premises creates a snapshot from a database file backup, requiring downtime and not supporting live replication."},"source_url":"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Task.CDC.html","tags":["dms","cdc","mysql","rds","zero-downtime","migration"],"verified":true},{"id":"09-a1b2c3d8","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS DataSync","difficulty":"medium","question":"A company needs to migrate 100 TB of data from an on-premises NAS (NFS share) to Amazon EFS on a weekly basis for the next 6 months. The data must be encrypted in transit and integrity-verified after transfer. Which service is most appropriate, and what key feature handles integrity verification?","options":{"A":"AWS Snowball Edge — ship weekly and import to EFS","B":"AWS DataSync with built-in data integrity verification and TLS encryption","C":"AWS Storage Gateway File Gateway — mount EFS locally and copy files","D":"rsync over a VPN connection — open source and flexible"},"correct":"B","explanation":"AWS DataSync is purpose-built for automated, recurring data transfers between on-premises storage (NFS, SMB, HDFS, S3-compatible) and AWS storage (S3, EFS, FSx). Key features: (1) Built-in data integrity verification — DataSync computes checksums during read, write, and after transfer, automatically retrying failed files. (2) TLS encryption in transit — all data is encrypted during transfer. (3) Scheduling — tasks can be scheduled daily, weekly, or hourly. (4) Up to 10x faster than open-source tools. DataSync agents are installed on-premises to connect to the NAS.","distractors":{"A":"Snowball Edge is optimal for one-time large migrations where network bandwidth is insufficient — shipping weekly for 6 months is operationally complex and expensive compared to DataSync's automated scheduled transfers.","C":"Storage Gateway File Gateway enables cloud-backed NFS/SMB access but is not designed for bulk one-time or periodic large-scale migrations — it optimizes ongoing access patterns, not bulk transfers.","D":"rsync over VPN works but lacks enterprise-grade integrity verification, automatic retry, bandwidth throttling, transfer metrics, and the performance optimizations that DataSync provides."},"source_url":"https://docs.aws.amazon.com/datasync/latest/userguide/what-is-datasync.html","tags":["datasync","nfs","efs","migration","integrity","encryption"],"verified":true},{"id":"09-a1b2c3d9","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Transfer Family","difficulty":"medium","question":"A financial institution receives daily files from 50 trading partners via SFTP. The files must be stored in S3 and processed by Lambda. The partners cannot change their SFTP workflow. Which service modernizes this workflow without breaking partner integrations?","options":{"A":"Create an EC2 instance running an SFTP server, then upload files to S3 via a Lambda cron job","B":"AWS Transfer Family for SFTP — provides a managed SFTP endpoint backed by S3 or EFS","C":"AWS DataSync with an SFTP source connector","D":"Amazon S3 with presigned POST URLs shared with each trading partner"},"correct":"B","explanation":"AWS Transfer Family provides fully managed SFTP (also FTPS, FTP, AS2) file transfer endpoints that store files directly in Amazon S3 or EFS. Trading partners continue using their existing SFTP clients with no changes — they authenticate using SSH keys or passwords. Files land directly in S3, triggering S3 event notifications → Lambda for automated processing. Transfer Family handles server management, scaling, and high availability.","distractors":{"A":"A self-managed EC2 SFTP server requires patching, scaling, key management, and operational overhead — plus a custom sync job to move files from the instance to S3, adding latency and complexity.","C":"DataSync supports NFS, SMB, HDFS, and S3-compatible sources — it does not have a native SFTP source connector for receiving inbound files from external partners.","D":"S3 presigned POST URLs require partners to change their workflow from SFTP to HTTPS — violating the requirement that partners cannot change their SFTP workflow."},"source_url":"https://docs.aws.amazon.com/transfer/latest/userguide/what-is-aws-transfer-family.html","tags":["transfer-family","sftp","s3","migration","trading-partners"],"verified":true},{"id":"09-a2b3c4d5","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS DataSync","difficulty":"hard","question":"A company uses AWS DataSync to transfer data from an on-premises NFS server to S3 daily. The DataSync task is configured with default settings and runs overnight. The network team reports that DataSync consumes the entire 1 Gbps WAN link during transfers, impacting business operations during the transfer window. Which DataSync feature limits bandwidth consumption?","options":{"A":"DataSync cannot limit bandwidth — use Snowball instead for large transfers","B":"Configure the DataSync task's bandwidth limit (MB/s) in the task schedule settings","C":"Reduce the task frequency from daily to weekly to reduce overall bandwidth","D":"Enable DataSync compression to reduce the data volume transferred"},"correct":"B","explanation":"AWS DataSync tasks support configuring a bandwidth limit in MB/s — you can set a maximum rate at which DataSync transfers data. This can also be set per schedule, so the task runs at full speed during off-peak hours (e.g., 2-4 AM) and at a throttled rate during business hours. The bandwidth limit is configured per task or per execution in the DataSync console or CLI, preventing DataSync from saturating the WAN link.","distractors":{"A":"DataSync does support bandwidth throttling — this is a built-in feature specifically designed for environments with shared WAN links.","C":"Reducing frequency from daily to weekly means data accumulates for 7 days and the single weekly transfer is 7x larger — this actually worsens the saturation problem and may violate RPO requirements.","D":"DataSync does compress data during transfer for eligible content, but this reduces data volume, not the rate of transfer — the link can still be saturated if uncompressed data rates are high."},"source_url":"https://docs.aws.amazon.com/datasync/latest/userguide/create-task.html","tags":["datasync","bandwidth","throttling","wan","network"],"verified":true},{"id":"09-b1c2d3e4","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"EventBridge and event-driven","difficulty":"medium","question":"A company uses multiple AWS services that generate events: EC2 state changes, S3 object creation, and CodePipeline state changes. They want a single service to capture ALL these events and route them to different Lambda functions, SQS queues, or Step Functions based on event content. Which service is designed for this centralized event routing?","options":{"A":"Amazon SNS with topic subscriptions for each event type","B":"Amazon SQS with multiple queues per service","C":"Amazon EventBridge with rules and targets","D":"AWS CloudTrail with CloudWatch Alarms"},"correct":"C","explanation":"Amazon EventBridge is a serverless event bus that receives events from AWS services, your own applications, and SaaS partners, then routes them to targets (Lambda, SQS, SNS, Step Functions, etc.) based on event pattern rules. Rules use JSON pattern matching on event content (e.g., route S3 events for .csv files to Processing Lambda, route CodePipeline failure events to Slack via an API destination). A single event bus handles events from all services without custom glue code.","distractors":{"A":"SNS delivers messages to subscribers but requires each service to explicitly publish to an SNS topic — most AWS services natively publish events to EventBridge, not SNS. SNS also lacks content-based routing rules.","B":"SQS requires producers to explicitly send to a queue — AWS services don't natively fan events to SQS. Multiple queues per service adds management overhead without content-based routing.","D":"CloudTrail records API activity in CloudWatch Logs for audit purposes — it is not an event routing service and adds latency. EventBridge natively receives EC2, S3, and CodePipeline events with millisecond delivery."},"source_url":"https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-what-is.html","tags":["eventbridge","event-routing","lambda","step-functions","event-driven"],"verified":true},{"id":"09-b1c2d3e5","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"EventBridge and event-driven","difficulty":"hard","question":"A company runs a financial reconciliation process that must execute every night at 11 PM UTC, invoking a Step Functions state machine. If the Step Functions execution fails, a notification must be sent to an SNS topic. Which EventBridge configuration implements both the schedule AND the failure notification?","options":{"A":"One EventBridge rule: cron schedule → Step Functions; configure Step Functions error handling to publish to SNS","B":"One EventBridge Scheduler schedule → Step Functions; one EventBridge rule matching Step Functions ExecutionFailed events → SNS","C":"Two CloudWatch Alarms: one for the schedule trigger, one monitoring Step Functions errors","D":"A Lambda function triggered by CloudWatch Events that runs the state machine and catches errors"},"correct":"B","explanation":"Two separate EventBridge configurations: (1) EventBridge Scheduler creates a cron schedule (\`cron(0 23 * * ? *)\`) targeting the Step Functions state machine — this replaces the need for a Lambda intermediary. (2) A separate EventBridge rule matches Step Functions state change events with status 'FAILED' (pattern: \`{\\"source\\":[\\"aws.states\\"],\\"detail-type\\":[\\"Step Functions Execution Status Change\\"],\\"detail\\":{\\"status\\":[\\"FAILED\\"]}}\`) and targets the SNS topic. This decouples the schedule from the failure notification.","distractors":{"A":"Step Functions can catch errors within state definitions but publishing directly to SNS from Step Functions requires a dedicated SNS state or manual task — the EventBridge approach is simpler and does not require modifying the state machine.","C":"CloudWatch Alarms monitor metrics (numerical thresholds) — they cannot trigger on schedule events or match Step Functions state change events by execution status.","D":"A Lambda intermediary adds cost and complexity — EventBridge Scheduler natively invokes Step Functions directly without needing a Lambda function as a proxy."},"source_url":"https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-create-rule-schedule.html","tags":["eventbridge","scheduler","step-functions","cron","sns","failure-notification"],"verified":true},{"id":"09-b1c2d3e6","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Step Functions","difficulty":"medium","question":"A company builds an order processing workflow with Step Functions. The workflow calls an external payment API that occasionally returns timeouts. The team wants Step Functions to retry the payment call up to 3 times with exponential backoff before marking the order as failed. How is this configured?","options":{"A":"Wrap the payment API call in a Lambda function that has its own retry loop","B":"Configure a Retry field on the Task state calling the payment API with MaxAttempts=3 and BackoffRate","C":"Use a Choice state to check the API response and loop back to the payment state on failure","D":"Set the Step Functions state machine timeout to retry automatically"},"correct":"B","explanation":"Step Functions Task states support a \`Retry\` field that defines retry behavior directly in the state machine definition. Configure: \`{\\"ErrorEquals\\":[\\"States.TaskFailed\\"],\\"IntervalSeconds\\":2,\\"MaxAttempts\\":3,\\"BackoffRate\\":2}\`. On a timeout, Step Functions waits 2 seconds, retries; waits 4 seconds (2×2), retries; waits 8 seconds, retries. After 3 failures, it transitions to the Catch handler (if configured) or fails the execution. This declarative retry eliminates custom retry logic in Lambda.","distractors":{"A":"Implementing retry logic inside Lambda adds complexity, consumes Lambda execution time during wait intervals (billable), and makes the retry behavior invisible in the Step Functions visual diagram.","C":"A Choice state loop re-enters the payment state on each failure but does not implement backoff — and it requires a separate Lambda check of the API response. The Retry field is the purpose-built solution.","D":"Step Functions state machine timeout is a maximum execution duration — it does not implement per-task retry logic or exponential backoff."},"source_url":"https://docs.aws.amazon.com/step-functions/latest/dg/concepts-error-handling.html#error-handling-retrying-after-an-error","tags":["step-functions","retry","exponential-backoff","task-state","error-handling"],"verified":true},{"id":"09-b1c2d3e7","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Step Functions","difficulty":"hard","question":"A company has two Step Functions workflow types: (1) Long-running human approval workflows that can take days or weeks and must preserve state across restarts. (2) High-volume microservice orchestrations executing thousands per second, each completing in seconds. Which Step Functions type should be used for each?","options":{"A":"Both should use Standard Workflows — they are more reliable","B":"Long-running approvals → Standard Workflow; high-volume short workflows → Express Workflow","C":"Long-running approvals → Express Workflow (Synchronous); short workflows → Standard Workflow","D":"Both should use Express Workflows for cost efficiency"},"correct":"B","explanation":"Step Functions offers two workflow types: Standard Workflows — execute exactly once with full execution history retained for 90 days. Max duration: 1 year. Billed per state transition. Suitable for long-running, durable workflows (human approvals, business processes). Express Workflows — designed for high-throughput (>100K events/second), short-duration (max 5 minutes). Billed per duration and requests. Asynchronous mode: at-least-once; Synchronous mode: at-most-once. Suitable for microservice orchestration, IoT ingestion, streaming processing.","distractors":{"A":"Standard Workflows are limited to 2,000 state transitions per second per account — insufficient for thousands of concurrent high-volume microservice orchestrations.","C":"Express Workflows have a maximum duration of 5 minutes — they cannot handle human approval workflows that take days or weeks.","D":"Express Workflows are cheaper for short, high-frequency executions but cannot satisfy the durability and long-running requirements of approval workflows."},"source_url":"https://docs.aws.amazon.com/step-functions/latest/dg/concepts-standard-vs-express.html","tags":["step-functions","standard-workflow","express-workflow","long-running","high-volume"],"verified":true},{"id":"09-b1c2d3e8","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"Amazon MQ","difficulty":"medium","question":"A company runs an on-premises Java application using ActiveMQ with JMS messaging. They want to migrate to AWS without rewriting the messaging code. Which AWS service provides a managed ActiveMQ broker with JMS compatibility?","options":{"A":"Amazon SQS — it supports JMS via the Amazon SQS Java Messaging Library","B":"Amazon MQ for ActiveMQ — fully managed ActiveMQ with native JMS, AMQP, STOMP, and OpenWire protocol support","C":"Amazon Kinesis Data Streams — it supports JMS consumers","D":"AWS IoT Core — it supports MQTT which is compatible with JMS"},"correct":"B","explanation":"Amazon MQ provides a fully managed message broker service supporting Apache ActiveMQ and RabbitMQ. It is protocol-compatible with JMS, AMQP, STOMP, MQTT, and OpenWire — allowing lift-and-shift migration by only changing the broker endpoint URL in the application configuration. No code changes to messaging producers or consumers are required. AWS manages patching, scaling, and multi-AZ active/standby high availability.","distractors":{"A":"Amazon SQS provides JMS compatibility via the Amazon SQS Java Messaging Library (JMS 1.1) but requires application-level changes to use SQS-specific concepts (queue URLs, message attributes) — it is not a drop-in replacement for an ActiveMQ broker.","C":"Amazon Kinesis Data Streams uses a proprietary streaming API (PutRecord, GetRecords, SubscribeToShard) — it does not support JMS or ActiveMQ protocols.","D":"AWS IoT Core supports MQTT for device connectivity — MQTT is a different protocol from JMS and is not compatible with JMS applications without significant code changes."},"source_url":"https://docs.aws.amazon.com/amazon-mq/latest/developer-guide/welcome.html","tags":["amazon-mq","activemq","jms","migration","messaging"],"verified":true},{"id":"09-b1c2d3e9","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS AppSync","difficulty":"medium","question":"A company builds a collaborative document editing application. Multiple users must see real-time updates when another user edits a shared document. The frontend uses React and the team wants a managed GraphQL API that pushes updates to all connected clients. Which AWS service is purpose-built for this?","options":{"A":"API Gateway REST API with Lambda integration","B":"AWS AppSync with GraphQL subscriptions","C":"API Gateway WebSocket API with connection management Lambda","D":"Amazon Kinesis Data Streams consumed by the frontend directly"},"correct":"B","explanation":"AWS AppSync is a managed GraphQL service that natively supports real-time subscriptions. When a mutation (e.g., document edit) is made, AppSync automatically pushes the update to all clients subscribed to that document via WebSocket connections — without the developer managing WebSocket connections or implementing pub/sub infrastructure. AppSync handles connection management, authentication (Cognito, IAM, API keys, OIDC), offline sync, and conflict resolution out of the box.","distractors":{"A":"API Gateway REST API is request-response — the server cannot push updates to clients. Clients would need to poll, adding latency and wasted requests.","C":"API Gateway WebSocket API + Lambda can implement real-time push but requires custom code: managing connection IDs in DynamoDB, routing mutations to subscribers, building the GraphQL layer — far more complex than AppSync's native subscriptions.","D":"Kinesis is designed for server-side stream consumers (Lambda, KCL applications) — web browser clients typically cannot directly consume Kinesis streams due to authentication complexity and the streaming API design."},"source_url":"https://docs.aws.amazon.com/appsync/latest/devguide/what-is-appsync.html","tags":["appsync","graphql","subscriptions","real-time","websocket"],"verified":true},{"id":"09-b2c3d4e5","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"Amazon AppFlow","difficulty":"medium","question":"A marketing team needs to automatically sync customer data from Salesforce to Amazon Redshift every hour, applying data transformations (masking email addresses, filtering inactive customers). The team has no engineering support and needs a no-code solution. Which AWS service enables this?","options":{"A":"AWS Glue ETL job scheduled via EventBridge","B":"Amazon AppFlow with Salesforce as source, Redshift as destination, and built-in transformations","C":"AWS Lambda polling the Salesforce API and writing to Redshift","D":"Amazon Kinesis Data Firehose with a Salesforce connector"},"correct":"B","explanation":"Amazon AppFlow is a fully managed integration service for bidirectional data transfer between SaaS applications (Salesforce, Zendesk, Slack, ServiceNow, Google Analytics) and AWS services (S3, Redshift, EventBridge). It requires zero code — configure via console with scheduling (every hour), field mapping, transformations (masking, truncation, filtering), and direct Redshift loading. AppFlow handles OAuth 2.0 authentication to Salesforce automatically.","distractors":{"A":"AWS Glue requires writing PySpark or Python ETL scripts to authenticate to Salesforce, retrieve data, transform it, and load to Redshift — significant engineering effort, violating the no-code requirement.","C":"A Lambda function polling Salesforce requires managing OAuth tokens, handling API rate limits, implementing retry logic, and writing transformation code — high engineering complexity for a non-technical team.","D":"Amazon Kinesis Data Firehose does not have a native Salesforce source connector for pulling data on a schedule — it receives streaming data pushed to it, not pulling from SaaS APIs."},"source_url":"https://docs.aws.amazon.com/appflow/latest/userguide/what-is-appflow.html","tags":["appflow","salesforce","redshift","integration","no-code","saas"],"verified":true},{"id":"09-c1d2e3f4","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Glue","difficulty":"medium","question":"A data engineering team has raw JSON log files arriving in S3 from multiple sources with varying schemas. They need to automatically discover the schema of each source, catalog the metadata, and run ETL jobs to convert JSON to Parquet. Which AWS Glue components handle each step?","options":{"A":"Glue Data Catalog → Glue Crawlers → Glue Jobs","B":"Glue Crawlers (schema discovery) → Glue Data Catalog (metadata storage) → Glue Jobs (ETL transformation)","C":"Glue Jobs → Glue Data Catalog → Glue Crawlers","D":"AWS DMS → Glue Data Catalog → Glue Jobs"},"correct":"B","explanation":"AWS Glue has three main components working in sequence: (1) Glue Crawlers — scan S3 data sources, infer schemas (column names, data types, partitions), and write table definitions. (2) Glue Data Catalog — a centralized metadata repository storing table schemas, partition information, and connection details. Shared by Athena, Redshift Spectrum, and EMR. (3) Glue Jobs — ETL scripts (PySpark or Python shell) that read source data using the Data Catalog schema and write transformed output (Parquet, ORC, CSV). Together they form a complete serverless ETL pipeline.","distractors":{"A":"The correct sequence is Crawlers first (they populate the catalog) then Jobs (they use the catalog) — the listed order (Catalog → Crawlers → Jobs) is backwards.","C":"Glue Jobs run after crawlers populate the catalog — running jobs first before schema discovery is impossible since the jobs need the catalog metadata.","D":"AWS DMS migrates databases between engines — it does not discover schemas of S3 JSON files or populate the Glue Data Catalog."},"source_url":"https://docs.aws.amazon.com/glue/latest/dg/what-is-glue.html","tags":["glue","crawlers","data-catalog","etl","parquet","s3"],"verified":true},{"id":"09-c1d2e3f5","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Glue","difficulty":"hard","question":"A Glue ETL job reads from a 10 TB S3 dataset partitioned by date. The job runs daily, transforming only the previous day's partition. Currently, the job scans the entire 10 TB dataset every run, which is slow and expensive. What Glue feature enables processing only the new partition?","options":{"A":"Glue Job Bookmarks — tracks previously processed S3 partitions and skips them on subsequent runs","B":"Glue Crawlers — re-crawl the dataset and filter new files automatically","C":"Glue trigger with a partition filter in the job arguments","D":"Glue DataBrew — automatically detects and processes new data"},"correct":"A","explanation":"AWS Glue Job Bookmarks enable incremental processing. Glue tracks the state of data that has been processed in previous job runs using S3 object metadata (last modified time, ETag). On the next run, Glue automatically skips previously processed files and only processes new or modified data. For date-partitioned S3 data, enabling bookmarks means the daily job reads only yesterday's partition instead of all 10 TB — reducing both execution time and DPU cost significantly.","distractors":{"B":"Glue Crawlers discover schema and partitions — they do not filter data for job processing. Crawlers populate the Data Catalog with metadata; jobs use that catalog but still read all data unless bookmarks are enabled.","C":"Glue triggers invoke jobs based on events or schedules — they do not filter data. A partition filter in job arguments would require custom code in the job script, not a native feature.","D":"AWS Glue DataBrew is a visual data preparation tool for data exploration and cleaning — it is not an ETL job orchestration tool and does not have incremental processing features for large-scale S3 datasets."},"source_url":"https://docs.aws.amazon.com/glue/latest/dg/monitor-continuations.html","tags":["glue","job-bookmarks","incremental","s3","partitions","etl"],"verified":true},{"id":"09-c1d2e3f6","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Lake Formation","difficulty":"medium","question":"A company builds a data lake on S3. Three teams need access: the Data Science team can query all data, the Marketing team can query only the \`customers\` table (but not the \`ssn\` column), and the Analytics team can query only rows where \`region = 'US'\`. Which service enforces this fine-grained column-level and row-level access control on the data lake?","options":{"A":"S3 bucket policies with prefix-based restrictions per team","B":"IAM policies with Athena workgroup restrictions","C":"AWS Lake Formation with column-level, row-level, and table-level permissions","D":"AWS Glue with ETL jobs creating filtered views per team"},"correct":"C","explanation":"AWS Lake Formation provides fine-grained access control for data lakes beyond what S3 bucket policies or IAM support natively: (1) Table-level: grant access to specific tables in the Data Catalog. (2) Column-level: exclude sensitive columns (like \`ssn\`) from specific principals. (3) Row-level: define row filters (e.g., \`region = 'US'\`) applied at query time. These permissions are enforced across Athena, Redshift Spectrum, and EMR queries — a single policy layer instead of per-service configuration.","distractors":{"A":"S3 bucket policies operate at the object/prefix level — they cannot filter specific columns within a Parquet file or apply row-level predicates based on data values.","B":"Athena workgroups limit query output location, query scan limits, and workgroup-level settings — they do not enforce column-level masking or row-level security on S3 data.","D":"Creating per-team ETL-filtered views means copying and maintaining separate dataset copies per team — expensive, complex to maintain, and does not prevent direct Athena access to the raw S3 data."},"source_url":"https://docs.aws.amazon.com/lake-formation/latest/dg/what-is-lake-formation.html","tags":["lake-formation","column-level-security","row-level-security","data-lake","athena","fine-grained"],"verified":true},{"id":"09-c1d2e3f7","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"Amazon MSK","difficulty":"medium","question":"A company runs Apache Kafka on self-managed EC2 instances. They spend significant time on Kafka broker patching, ZooKeeper management, and rebalancing. They want a managed Kafka service while preserving existing Kafka client code and configuration. Which service should they migrate to?","options":{"A":"Amazon Kinesis Data Streams — it is the AWS replacement for Kafka","B":"Amazon MSK (Managed Streaming for Apache Kafka) — fully managed Kafka with protocol compatibility","C":"Amazon SQS FIFO — it provides the same ordering guarantees as Kafka","D":"AWS IoT Core — it provides managed message streaming"},"correct":"B","explanation":"Amazon MSK (Managed Streaming for Apache Kafka) provides fully managed Apache Kafka clusters. AWS handles: broker provisioning, patching, ZooKeeper management, configuration, monitoring, and storage scaling. Applications using the Kafka client library can connect to MSK with only an endpoint change — zero code changes. MSK also supports Kafka-native APIs, Kafka Connect, and MSK Serverless (auto-scaling). This is a lift-and-shift migration from self-managed Kafka to managed Kafka.","distractors":{"A":"Kinesis Data Streams uses a proprietary AWS API (PutRecord, GetRecords) — it is NOT Kafka-compatible. Existing Kafka client code would require significant rewrites to work with Kinesis.","C":"SQS FIFO provides exactly-once, ordered delivery within message groups but does not support Kafka's consumer group model, partition-based sharding, log retention, or Kafka client libraries — not a Kafka replacement.","D":"AWS IoT Core is a device connectivity platform for IoT workloads using MQTT — it has no Kafka protocol compatibility."},"source_url":"https://docs.aws.amazon.com/msk/latest/developerguide/what-is-msk.html","tags":["msk","kafka","managed","migration","streaming","protocol-compatible"],"verified":true},{"id":"09-c1d2e3f8","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"Amazon MSK","difficulty":"hard","question":"A company uses Amazon MSK with Kafka producers at 500 MB/s aggregate throughput. They want a second consumer group to process the same stream for real-time fraud detection — without impacting the throughput available to the existing analytics consumer group. What is unique about MSK's consumer model that enables this?","options":{"A":"MSK automatically creates a copy of each partition for each consumer group","B":"Kafka's consumer group model allows multiple independent consumer groups to read the same partitions simultaneously without competing — each group maintains its own offset pointer","C":"MSK Enhanced Fan-Out provides dedicated throughput per consumer group, similar to Kinesis","D":"MSK requires a separate MSK cluster per consumer group to prevent throughput competition"},"correct":"B","explanation":"Apache Kafka (and MSK) natively supports multiple independent consumer groups reading the same topic partitions. Each consumer group maintains its own offset (position in the partition) — so the fraud detection group and analytics group each independently consume all messages at their own pace without competing. Read throughput scales with the number of brokers/partitions. This is a fundamental difference from SQS (which uses competing consumers that share messages).","distractors":{"A":"Kafka does not copy partitions per consumer group — all consumer groups read from the same underlying partition log, each tracking their own offset.","C":"MSK Enhanced Fan-Out does not exist — this is a Kinesis Data Streams feature. Kafka's native multi-consumer-group model naturally provides parallel consumption without additional configuration.","D":"A separate MSK cluster per consumer group would multiply cost and operational overhead unnecessarily — Kafka's partition model inherently supports multiple concurrent consumer groups."},"source_url":"https://docs.aws.amazon.com/msk/latest/developerguide/what-is-msk.html","tags":["msk","kafka","consumer-groups","offset","multi-consumer","streaming"],"verified":true},{"id":"09-c2d3e4f5","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"Amazon QuickSight","difficulty":"medium","question":"A business intelligence team publishes QuickSight dashboards to 5,000 employees. The underlying dataset is a 500 GB RDS PostgreSQL table that must be queried in real-time. During peak hours, dashboard loads take 45 seconds. Which QuickSight feature improves dashboard performance for large datasets?","options":{"A":"Import the dataset into QuickSight SPICE (Super-fast, Parallel, In-memory Calculation Engine)","B":"Enable QuickSight multi-AZ for the RDS connection","C":"Add a QuickSight Reader account for each employee","D":"Use QuickSight paginated reports instead of interactive dashboards"},"correct":"A","explanation":"SPICE (Super-fast, Parallel, In-memory Calculation Engine) is QuickSight's in-memory calculation engine. Importing datasets into SPICE pre-loads the data into a massively parallel, columnar in-memory store — dashboards query SPICE instead of the live RDS database. SPICE queries return in milliseconds vs. seconds for live database queries. SPICE data is refreshed on a schedule (hourly, daily) or via API. For 500 GB at 5,000 users, SPICE eliminates database load and achieves sub-second dashboard performance.","distractors":{"B":"QuickSight connects to RDS as a data source — it does not have 'Multi-AZ' settings for RDS connections. Multi-AZ is an RDS configuration for availability, not QuickSight performance.","C":"QuickSight Reader accounts control access pricing but do not affect dashboard query performance or speed.","D":"Paginated reports are for static, print-ready reports (e.g., PDF) — they do not improve interactive dashboard performance and serve a different use case entirely."},"source_url":"https://docs.aws.amazon.com/quicksight/latest/user/spice.html","tags":["quicksight","spice","bi","performance","in-memory","dashboard"],"verified":true},{"id":"09-c2d3e4f6","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"Kinesis Data Analytics","difficulty":"medium","question":"A company streams clickstream events to Kinesis Data Streams. They want to detect anomalies in real-time — specifically, when any product page receives more than 1,000 views in a 5-minute sliding window — and trigger an alert. Which service enables real-time SQL-based stream processing with windowed aggregations?","options":{"A":"AWS Glue Streaming ETL job","B":"Amazon Kinesis Data Analytics for SQL (Managed Service for Apache Flink)","C":"Amazon Athena querying Kinesis Data Streams directly","D":"AWS Lambda consuming Kinesis and running counts in memory"},"correct":"B","explanation":"Amazon Kinesis Data Analytics (now Managed Service for Apache Flink) enables real-time stream processing using Apache Flink — which supports SQL-like queries with time-based windowing (tumbling, sliding, session windows). A sliding 5-minute window aggregation on product page views is a native Flink/SQL operation. Results can be sent to Kinesis, Lambda, S3, or OpenSearch for alerting. For SQL-based anomaly detection on streaming data, Kinesis Data Analytics is the purpose-built managed service.","distractors":{"A":"AWS Glue Streaming ETL supports Apache Spark Streaming for micro-batch processing — it is designed for ETL transformations, not real-time sub-second window aggregations for anomaly detection.","C":"Amazon Athena is designed for querying S3 data — it does not directly query Kinesis Data Streams in real-time. There is an Athena connector for Kinesis but it is not optimized for continuous real-time windowed aggregations.","D":"Lambda consuming Kinesis and maintaining counts in memory works for simple aggregations but is stateless across invocations — maintaining accurate 5-minute sliding window state across thousands of concurrent Lambda instances requires complex external state management (DynamoDB), which Kinesis Data Analytics handles natively."},"source_url":"https://docs.aws.amazon.com/kinesisanalytics/latest/java/what-is.html","tags":["kinesis-analytics","flink","real-time","windowing","streaming","sql"],"verified":true},{"id":"09-d1e2f3g4","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"IAM Access Analyzer","difficulty":"medium","question":"A security team wants to identify all S3 buckets, IAM roles, KMS keys, and SQS queues in their account that are accessible by principals outside the account (external entities like other AWS accounts, IAM users in other accounts, or anonymous public access). Which service automates this discovery?","options":{"A":"AWS Trusted Advisor — checks for public S3 buckets and security group exposures","B":"Amazon GuardDuty — detects unusual cross-account access patterns","C":"IAM Access Analyzer — analyzes resource policies to identify external access","D":"AWS Config — evaluates resource configurations for public access"},"correct":"C","explanation":"IAM Access Analyzer uses automated reasoning (provable security) to analyze resource-based policies (S3 bucket policies, IAM role trust policies, KMS key policies, SQS queue policies, Lambda function policies, Secrets Manager secrets) and identifies any resource that grants access to external principals (outside the analyzed zone of trust — typically the AWS account or organization). It generates findings for each external-access resource, helping security teams identify unintended sharing within minutes of enabling it.","distractors":{"A":"Trusted Advisor checks S3 bucket public access and security group configurations — it does not analyze IAM role trust policies, KMS key policies, or SQS queue policies for external access.","B":"GuardDuty detects behavioral anomalies from logs (unusual API calls, suspicious access) — it does not statically analyze resource policies to find externally accessible resources before they are actually accessed.","D":"AWS Config evaluates whether specific configurations comply with rules (e.g., 's3-bucket-public-read-prohibited') — it checks individual settings but does not perform the comprehensive policy reasoning that Access Analyzer does across all resource types."},"source_url":"https://docs.aws.amazon.com/IAM/latest/UserGuide/what-is-access-analyzer.html","tags":["iam-access-analyzer","external-access","s3","kms","cross-account","security"],"verified":true},{"id":"09-d1e2f3g5","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"AWS Firewall Manager","difficulty":"medium","question":"A company has 50 AWS accounts under AWS Organizations. Security policy requires that AWS WAF with a specific rule group is applied to all ALBs across all accounts — including new accounts that join the organization. Which service enforces this centrally and automatically?","options":{"A":"Deploy WAF rules via CloudFormation StackSets to all accounts","B":"AWS Firewall Manager with a WAF policy applied to the organization","C":"IAM SCPs preventing ALBs from being created without WAF","D":"AWS Config with a custom rule remediating ALBs without WAF"},"correct":"B","explanation":"AWS Firewall Manager centralizes security policy management across AWS Organizations. A WAF policy in Firewall Manager specifies which WAF rule groups to apply and which resources (ALBs, CloudFront, API Gateway) to protect. Firewall Manager automatically applies the policy to existing and NEW accounts that join the organization — no manual intervention needed for new accounts. It also provides compliance reporting, showing which accounts/resources are non-compliant.","distractors":{"A":"CloudFormation StackSets can deploy WAF rules across accounts but requires manual updates when new accounts join and does not automatically detect non-compliant resources or remediate drift.","C":"SCPs cannot enforce that ALBs have WAF associated — SCPs control what actions can be taken (e.g., prevent CreateWebACL) but cannot enforce association requirements for existing resources.","D":"AWS Config with custom remediation can detect and fix individual non-compliant resources but requires creating and maintaining the rule and Lambda remediation function separately per account — far more operational overhead than Firewall Manager."},"source_url":"https://docs.aws.amazon.com/waf/latest/developerguide/fms-chapter.html","tags":["firewall-manager","waf","organizations","centralized","alb","security-policy"],"verified":true},{"id":"09-d1e2f3g6","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"Amazon Detective","difficulty":"medium","question":"After GuardDuty generates a finding 'UnauthorizedAccess:IAMUser/ConsoleLoginSuccess.B' (successful console login from an unusual location), a security analyst must investigate whether this represents a compromised IAM user — tracing all API calls made, resources accessed, and related network activity. Which service provides a graphical investigation interface for this?","options":{"A":"AWS CloudTrail — query CloudTrail logs with Athena","B":"Amazon Detective — provides automatic graph-based visualizations of security findings and related activity","C":"AWS Security Hub — shows the finding severity and CVSS score","D":"Amazon GuardDuty — click 'investigate' to expand the finding"},"correct":"B","explanation":"Amazon Detective automatically ingests CloudTrail, VPC Flow Logs, and GuardDuty findings and uses machine learning to build a graph model of AWS resource behavior. When a GuardDuty finding occurs, Detective provides a visual investigation console showing: which IAM user was involved, all API calls they made, resources they accessed, IP addresses they connected from, and how their behavior compares to their baseline. This reduces investigation time from hours to minutes compared to manually querying CloudTrail logs.","distractors":{"A":"Querying CloudTrail logs in Athena can answer specific questions about API calls but requires writing SQL queries, joining multiple log sources, and lacks the automated behavioral baseline comparison that Detective provides.","C":"Security Hub aggregates and prioritizes findings from multiple services with a severity score — it does not provide graph-based investigation or behavioral analysis of the finding's impact.","D":"GuardDuty generates findings and provides basic finding details — it does not have a built-in investigation interface for tracing all activity associated with the finding."},"source_url":"https://docs.aws.amazon.com/detective/latest/adminguide/what-is-detective.html","tags":["detective","guardduty","investigation","security","iam","graph"],"verified":true},{"id":"09-d1e2f3g7","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"AWS CloudHSM","difficulty":"hard","question":"A healthcare company must comply with FIPS 140-2 Level 3 validation for all cryptographic operations. They need to generate and store private keys for a PKI (Public Key Infrastructure) with full control — the key material must never leave the hardware device. Which AWS service meets this requirement?","options":{"A":"AWS KMS with a customer-managed CMK — keys are stored in FIPS 140-2 Level 2 validated HSMs","B":"AWS CloudHSM — dedicated single-tenant HSM appliances validated to FIPS 140-2 Level 3","C":"AWS Secrets Manager — stores private keys encrypted at rest","D":"ACM Private CA — provides PKI with automatic key management"},"correct":"B","explanation":"AWS CloudHSM provides dedicated, single-tenant Hardware Security Module (HSM) appliances in your VPC. CloudHSM is FIPS 140-2 Level 3 validated — the highest HSM security level available on AWS. Key material never leaves the HSM in plaintext and cannot be accessed by AWS. You manage the HSM cluster and cryptographic operations directly using standard APIs (PKCS#11, JCE, OpenSSL). CloudHSM is required for compliance frameworks that mandate Level 3 HSMs (vs. Level 2 for KMS).","distractors":{"A":"AWS KMS CMKs are stored in FIPS 140-2 Level 2 validated HSMs — not Level 3. For Level 3 FIPS compliance, CloudHSM is required. KMS also involves AWS managing key material in their HSM fleet.","C":"AWS Secrets Manager encrypts secrets using KMS (Level 2 HSMs) and is for storing and rotating application credentials — it is not an HSM for cryptographic operations or PKI key generation.","D":"ACM Private CA provides a managed CA service that uses KMS for key storage (Level 2) — it does not provide FIPS 140-2 Level 3 HSM validation or the full PKI control required."},"source_url":"https://docs.aws.amazon.com/cloudhsm/latest/userguide/introduction.html","tags":["cloudhsm","fips","pki","encryption","hsm","level3"],"verified":true},{"id":"09-d1e2f3g8","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"AWS Directory Service","difficulty":"medium","question":"A company uses on-premises Active Directory (AD) to authenticate employees. They deploy AWS Workspaces for remote workers who need to log in with their existing AD credentials. The on-premises AD must remain the source of truth for authentication. Which AWS Directory Service configuration achieves this?","options":{"A":"Create AWS Managed Microsoft AD — a standalone directory with no connection to on-premises AD","B":"Create AWS AD Connector — a proxy that forwards authentication requests to the on-premises AD","C":"Create AWS Simple AD — a Samba-based AD for small organizations","D":"Use Cognito User Pools to replicate the on-premises AD users"},"correct":"B","explanation":"AWS AD Connector is a directory gateway (proxy) that forwards all authentication requests from AWS services (WorkSpaces, WorkDocs, EC2 domain join, AWS SSO) to the existing on-premises Active Directory. No directory data is cached in AWS — all authentications go to on-premises AD in real-time. Users authenticate with their existing AD credentials without managing a second directory or synchronizing users. AD Connector requires network connectivity (Direct Connect or VPN) between the VPC and on-premises AD.","distractors":{"A":"AWS Managed Microsoft AD creates a new, standalone AD in the cloud — it does not authenticate against the on-premises AD by default. It can have a trust relationship configured, but that is more complex than AD Connector for this use case.","C":"AWS Simple AD is a Samba 4-based standalone lightweight directory for small organizations — it is not compatible with Microsoft AD authentication and cannot proxy to an on-premises AD.","D":"Cognito User Pools are for application user pools (web/mobile apps) — they do not integrate with corporate AD for AWS service authentication like WorkSpaces or EC2 domain join."},"source_url":"https://docs.aws.amazon.com/directoryservice/latest/admin-guide/directory_ad_connector.html","tags":["directory-service","ad-connector","active-directory","workspaces","authentication"],"verified":true},{"id":"09-d2e3f4g5","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"AWS Artifact","difficulty":"easy","question":"A company's legal and compliance team needs AWS's SOC 2 Type II report and BAA (Business Associate Agreement) for a HIPAA compliance audit. Where can they access these documents self-service without contacting AWS Support?","options":{"A":"AWS Security Hub compliance dashboard","B":"AWS Artifact — on-demand access to AWS compliance reports and agreements","C":"AWS Config conformance packs with HIPAA framework","D":"AWS Trusted Advisor security checks"},"correct":"B","explanation":"AWS Artifact is a self-service portal in the AWS Management Console that provides on-demand access to AWS compliance documentation: (1) Reports — SOC 1/2/3, PCI DSS, ISO 27001, FedRAMP, and more, downloadable as PDFs. (2) Agreements — Business Associate Addendum (BAA) for HIPAA, Non-Disclosure Agreements (NDAs) — can be accepted/downloaded directly in the console. This eliminates the need to contact AWS Support or account managers for standard compliance documentation.","distractors":{"A":"AWS Security Hub provides security findings and compliance checks against frameworks (CIS, PCI) for your AWS environment — it does not provide AWS's own compliance certifications or legal agreements.","C":"AWS Config conformance packs evaluate your resource configurations against compliance frameworks (HIPAA, PCI) — they check YOUR environment's compliance, not provide AWS's own audit reports or legal agreements.","D":"Trusted Advisor identifies best-practice deviations in your AWS environment — it does not provide access to AWS compliance certifications or legal agreements."},"source_url":"https://docs.aws.amazon.com/artifact/latest/ug/what-is-aws-artifact.html","tags":["artifact","compliance","soc2","hipaa","baa","audit"],"verified":true},{"id":"09-e1f2g3h4","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Wavelength and edge compute","difficulty":"medium","question":"A mobile gaming company wants to deploy game server logic that responds to player actions with under 10ms round-trip latency for users on 5G networks. Players' 5G traffic must stay within the telecom carrier's network and not traverse the public internet to reach AWS. Which AWS infrastructure is purpose-built for this?","options":{"A":"AWS Local Zones — extends AWS to major metro areas","B":"AWS Wavelength — deploys AWS compute and storage at the edge of 5G carrier networks","C":"Amazon CloudFront with Lambda@Edge","D":"AWS Global Accelerator with NLB endpoints"},"correct":"B","explanation":"AWS Wavelength embeds AWS compute (EC2, ECS) and storage (EBS) directly within telecommunications providers' 5G networks (Verizon, Vodafone, KDDI). Application traffic from 5G devices reaches the Wavelength Zone without leaving the carrier's network, providing single-digit millisecond latency (vs. 20-100ms to a regular AWS region). Developers deploy applications in Wavelength Zones using the same AWS APIs they use in standard regions — no new skills required.","distractors":{"A":"AWS Local Zones extend AWS infrastructure to metro areas (e.g., Los Angeles, Boston) — they reduce latency to ~1-10ms for users in that city but still route over the public internet, not within the 5G carrier network.","C":"CloudFront Lambda@Edge executes lightweight functions at CloudFront PoPs — it adds network hops between the 5G device and the function and does not eliminate public internet traversal for latency-sensitive gaming traffic.","D":"Global Accelerator routes traffic over the AWS backbone to reduce internet variability — but traffic still traverses the internet from the 5G device to the nearest AWS edge node (not within the carrier network)."},"source_url":"https://docs.aws.amazon.com/wavelength/latest/developerguide/what-is-wavelength.html","tags":["wavelength","5g","edge-computing","gaming","low-latency","telecom"],"verified":true},{"id":"09-e1f2g3h5","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"Route 53 Resolver Endpoints","difficulty":"medium","question":"A company has a hybrid environment with on-premises DNS servers (running BIND) that resolve internal hostnames (e.g., database.corp.internal). EC2 instances in a VPC need to resolve these on-premises hostnames. Additionally, on-premises servers need to resolve private Route 53 hosted zone names (e.g., rds.internal.aws). Which Route 53 component enables bidirectional DNS resolution?","options":{"A":"Route 53 Private Hosted Zone only — it handles all DNS resolution automatically","B":"Route 53 Resolver Inbound Endpoint (on-premises → AWS) and Outbound Endpoint (AWS → on-premises) with forwarding rules","C":"Create a CNAME record in the public Route 53 hosted zone pointing to on-premises servers","D":"Install a BIND DNS server on an EC2 instance to relay queries"},"correct":"B","explanation":"Route 53 Resolver Endpoints enable bidirectional DNS resolution between AWS and on-premises: (1) Inbound Endpoint — creates ENIs in your VPC. On-premises DNS servers forward queries for AWS private zones (rds.internal.aws) to these IPs, which Route 53 Resolver resolves. (2) Outbound Endpoint — when EC2 instances query on-premises hostnames (database.corp.internal), resolver forwarding rules redirect the query to the on-premises DNS server IPs through the Outbound Endpoint. This replaces the need for custom EC2-based DNS servers.","distractors":{"A":"A Private Hosted Zone only resolves AWS-internal names for VPC resources — it cannot forward queries to on-premises DNS servers or resolve on-premises hostnames.","C":"CNAME records in a public hosted zone expose internal names to the internet — not appropriate for private hybrid DNS. Public records also cannot resolve RFC 1918 private IP addresses.","D":"A BIND server on EC2 works but requires ongoing management (patching, HA configuration, scaling) — Route 53 Resolver Endpoints are the managed AWS alternative with automatic redundancy."},"source_url":"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/resolver.html","tags":["route53","resolver","hybrid","dns","inbound-endpoint","outbound-endpoint","on-premises"],"verified":true},{"id":"09-e1f2g3h6","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"ECS Anywhere","difficulty":"medium","question":"A company runs containerized applications on Kubernetes in their own data center. They want to manage and deploy these containers using Amazon ECS without migrating to AWS cloud. The on-premises servers must remain the execution environment. Which AWS service enables this?","options":{"A":"Amazon EKS with self-managed node groups in the on-premises data center","B":"Amazon ECS Anywhere — registers on-premises servers as ECS external instances","C":"AWS Outposts — deploys AWS infrastructure in the data center","D":"AWS Snowball Edge Compute Optimized — runs ECS containers offline"},"correct":"B","explanation":"Amazon ECS Anywhere allows registering on-premises servers (or VMs on any cloud) as ECS 'external instances' using the ECS agent and SSM agent. Once registered, ECS can deploy and manage containers on these on-premises servers using the same ECS task definitions, services, and CLI/console as cloud ECS workloads. AWS provides centralized control plane visibility, deployment management, and integration with ECR — while the actual containers run on-premises. There is no need to migrate workloads to AWS.","distractors":{"A":"Amazon EKS with self-managed node groups deploys Kubernetes worker nodes on EC2 instances in AWS — it does not manage on-premises servers. EKS Anywhere is a separate product for running EKS on on-premises infrastructure.","C":"AWS Outposts ships AWS rack infrastructure to the data center — it runs AWS services (EC2, EBS, RDS) on dedicated hardware owned by AWS. It requires purchasing Outposts hardware and is much more than just container management.","D":"Snowball Edge is a portable data storage and compute device for disconnected, edge environments — it is not designed for managing on-premises servers as persistent container execution environments."},"source_url":"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-anywhere.html","tags":["ecs-anywhere","on-premises","containers","hybrid","external-instances"],"verified":true},{"id":"09-e1f2g3h7","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Batch","difficulty":"medium","question":"A genomics company runs thousands of DNA sequence analysis jobs per day. Each job requires different compute resources (some need 4 vCPUs/16 GB RAM, others need 96 vCPUs/384 GB RAM). Jobs are independent and can be submitted simultaneously. Which AWS service is most appropriate for managing this heterogeneous batch compute workload?","options":{"A":"AWS Lambda with parallel invocations","B":"AWS Batch with managed compute environments and job queues","C":"AWS Step Functions with parallel state branches","D":"Amazon ECS with a single task definition for all jobs"},"correct":"B","explanation":"AWS Batch is purpose-built for batch computing workloads. It: (1) Manages compute environments (EC2 On-Demand or Spot) that dynamically scale based on queue depth. (2) Supports job definitions with different vCPU/memory requirements per job type. (3) Queues jobs and schedules them when appropriate compute resources are available. (4) Integrates with Spot Instances for up to 90% cost savings on fault-tolerant genomics workloads. AWS Batch eliminates the need to run idle compute clusters — resources are provisioned on demand and terminated when jobs complete.","distractors":{"A":"Lambda has a maximum memory of 10 GB and 15-minute timeout — insufficient for genomics jobs requiring 384 GB RAM or potentially hours of processing. Lambda also cannot efficiently manage thousands of heterogeneous compute configurations.","C":"Step Functions orchestrates workflow logic (branching, retry, error handling) — it does not manage compute provisioning or run batch compute workloads directly. Step Functions can invoke Batch as part of a workflow, but is not the compute layer.","D":"ECS with a single task definition cannot accommodate heterogeneous resource requirements (4 vCPUs vs 96 vCPUs jobs) without multiple task definitions and custom scheduling logic — Batch handles this natively."},"source_url":"https://docs.aws.amazon.com/batch/latest/userguide/what-is-batch.html","tags":["batch","genomics","compute","hpc","heterogeneous","spot"],"verified":true},{"id":"09-f1g2h3i4","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Migration Hub","difficulty":"easy","question":"A company migrates 300 applications to AWS using a mix of AWS Application Migration Service (MGN), AWS DMS, and AWS DataSync. The project manager needs a single dashboard to track the migration progress of all applications across all tools. Which AWS service provides this unified view?","options":{"A":"AWS Cost Explorer — shows cloud spending as applications migrate","B":"AWS Migration Hub — centralized tracking of migrations from multiple tools","C":"Amazon CloudWatch — monitors the health of migrated applications","D":"AWS Systems Manager — provides an inventory of all migrated servers"},"correct":"B","explanation":"AWS Migration Hub provides a single location to track the progress of application migrations across multiple AWS and partner migration tools. It aggregates status from MGN, DMS, CloudEndure, and many partner tools into a unified application-centric view. The project manager sees per-application status (Not Started, In Progress, Completed), the tools used, and discovered resources — without switching between multiple tool consoles. Migration Hub also integrates with Application Discovery Service to build an inventory before migration begins.","distractors":{"A":"Cost Explorer tracks AWS spending — it does not track migration progress, application status, or which servers have been migrated.","C":"CloudWatch monitors operational health (CPU, memory, error rates) of running AWS resources — it does not track the migration status of applications moving from on-premises.","D":"Systems Manager provides inventory and patch management for running EC2 instances — it does not aggregate migration progress from tools like MGN, DMS, or DataSync."},"source_url":"https://docs.aws.amazon.com/migrationhub/latest/ug/what-is-migration-hub.html","tags":["migration-hub","mgn","dms","migration-tracking","centralized"],"verified":true},{"id":"09-f1g2h3i5","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"AWS Audit Manager","difficulty":"medium","question":"A company must continuously collect evidence for their PCI DSS audit. They need to automatically gather AWS Config rule evaluation results, CloudTrail events, and Security Hub findings that map to specific PCI DSS controls, and package them into an audit report. Which AWS service automates this evidence collection?","options":{"A":"AWS Artifact — provides pre-built compliance reports","B":"AWS Audit Manager — automates evidence collection mapped to compliance frameworks","C":"AWS Security Hub with PCI DSS standard enabled","D":"AWS Config conformance packs with PCI DSS controls"},"correct":"B","explanation":"AWS Audit Manager continuously collects evidence (AWS Config evaluations, CloudTrail API activities, Security Hub findings, AWS service configurations) and automatically maps it to controls within compliance frameworks (PCI DSS, HIPAA, SOC 2, GDPR, ISO 27001). At audit time, Audit Manager generates assessment reports with evidence already organized by control — eliminating the manual evidence collection that typically takes weeks. Audit managers can review, flag, and submit evidence through the Audit Manager console.","distractors":{"A":"AWS Artifact provides AWS's own compliance documentation (SOC 2 reports, ISO certificates) — it does not collect evidence about YOUR AWS environment's compliance posture.","C":"Security Hub with PCI DSS standard evaluates your environment against PCI controls and generates findings — but it does not package evidence into audit reports or map findings to specific control requirements across multiple data sources.","D":"Config conformance packs evaluate resource configurations against PCI controls — but they only cover Config rules, not CloudTrail events or Security Hub findings, and do not generate audit reports."},"source_url":"https://docs.aws.amazon.com/audit-manager/latest/userguide/what-is.html","tags":["audit-manager","pci-dss","compliance","evidence","automation","audit"],"verified":true},{"id":"09-f1g2h3i6","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"Amazon QuickSight","difficulty":"hard","question":"A company has 10,000 employees who need access to QuickSight dashboards. 9,000 employees only view dashboards (never create them), while 1,000 employees create and edit analyses. Which QuickSight pricing model minimizes cost for this user distribution?","options":{"A":"Purchase 10,000 Author licenses ($18/user/month = $180,000/month)","B":"Purchase 1,000 Author licenses ($18/user/month) + 9,000 Reader licenses ($5/session or max $5/month/user)","C":"Use QuickSight Enterprise with unlimited users at a flat fee","D":"Purchase 10,000 Reader licenses and give Authors the same Reader license"},"correct":"B","explanation":"QuickSight has two license types: Author ($18/user/month) — can create analyses, datasets, and dashboards. Reader — can only view shared dashboards, charged per-session (up to $5/month/user cap). For 9,000 view-only users, Reader licenses at ≤$5/month = max $45,000/month vs. Author at $162,000/month. For 1,000 Authors at $18 = $18,000/month. Total: max $63,000/month vs. $180,000/month for all Authors — a 65% cost reduction by correctly tiering license types.","distractors":{"A":"Purchasing Author licenses for 9,000 view-only employees wastes $162,000/month — Reader pricing is specifically designed for dashboard consumers.","C":"QuickSight does not have an 'unlimited users flat fee' tier — pricing is per Author and per Reader session.","D":"Readers cannot create or edit analyses — giving Authors a Reader license prevents them from doing their job of building dashboards."},"source_url":"https://aws.amazon.com/quicksight/pricing/","tags":["quicksight","pricing","author","reader","cost","license"],"verified":true},{"id":"09-g1h2i3j4","version":1,"setId":"set-09","domain":"Resilient Architectures","topic":"AWS Application Discovery Service","difficulty":"easy","question":"A company is planning a migration of 500 on-premises servers to AWS. Before migrating, they need an accurate inventory of all servers, their configurations, CPU/memory utilization, and network dependencies between applications. Which AWS service discovers this information automatically?","options":{"A":"AWS Config — records AWS resource configurations","B":"AWS Application Discovery Service — discovers and maps on-premises infrastructure","C":"AWS Systems Manager Inventory — inventories AWS EC2 instances","D":"Amazon Inspector — scans on-premises servers for vulnerabilities"},"correct":"B","explanation":"AWS Application Discovery Service (ADS) discovers on-premises infrastructure through two methods: (1) Agentless Discovery — deploys a VMware vCenter-based collector virtual appliance, collecting VM configurations and utilization without touching individual VMs. (2) Agent-based Discovery — installs a lightweight agent on each server, collecting detailed OS-level data (processes, network connections, software). ADS feeds data into AWS Migration Hub, providing network dependency maps that guide application grouping for migration waves.","distractors":{"A":"AWS Config records configurations of AWS resources (EC2, RDS, S3) — it does not discover or inventory on-premises servers before migration.","C":"AWS Systems Manager Inventory collects software and configuration inventory from managed EC2 instances and on-premises servers that have the SSM agent installed — but it requires the SSM agent and focuses on software inventory, not migration dependency mapping.","D":"Amazon Inspector scans EC2 instances and container images for software vulnerabilities — it does not discover on-premises infrastructure or map application dependencies for migration planning."},"source_url":"https://docs.aws.amazon.com/application-discovery/latest/userguide/what-is-appdiscovery.html","tags":["application-discovery","migration","inventory","dependency-mapping","on-premises"],"verified":true},{"id":"09-g1h2i3j5","version":1,"setId":"set-09","domain":"High-Performing Architectures","topic":"AWS Glue","difficulty":"medium","question":"A company has AWS Glue ETL jobs that process sensitive customer data containing credit card numbers. The compliance team requires that credit card numbers be masked in the output before writing to S3. Which AWS Glue feature enables built-in sensitive data detection and masking without writing custom code?","options":{"A":"Glue Data Quality — detects anomalies in data patterns","B":"AWS Glue DataBrew with sensitive data detection transformations","C":"Glue FindMatches ML transform for deduplication","D":"Glue Data Catalog column-level metadata tagging"},"correct":"B","explanation":"AWS Glue DataBrew is a visual data preparation service with built-in sensitive data detection. DataBrew can automatically detect patterns matching PII (credit card numbers, SSNs, phone numbers, email addresses) using regex patterns and ML-based detection, then apply transformations like masking (replace with asterisks), hashing, or substitution. This requires no Python/Spark code — recipes are defined visually or via API. The processed, masked data is then written to S3.","distractors":{"A":"AWS Glue Data Quality monitors data completeness, uniqueness, and statistical patterns — it detects data quality issues like nulls, duplicates, and range violations, but not semantic PII patterns like credit card numbers.","C":"Glue FindMatches is an ML transform for entity resolution (finding duplicate records) — it does not detect or mask sensitive data.","D":"Glue Data Catalog column metadata (including tagging columns as sensitive) is documentation — it does not apply data masking transformations to the actual data values."},"source_url":"https://docs.aws.amazon.com/glue/latest/dg/databrew-sensitive-data.html","tags":["glue","databrew","pii","masking","sensitive-data","compliance"],"verified":true},{"id":"09-g1h2i3j6","version":1,"setId":"set-09","domain":"Secure Architectures","topic":"IAM Access Analyzer","difficulty":"hard","question":"A developer writes an IAM policy and wants to validate it before deploying it to production to ensure it doesn't grant overly broad permissions or contain policy errors. Which IAM Access Analyzer capability checks policies BEFORE they are deployed?","options":{"A":"IAM Access Analyzer external access analysis — scans deployed resource policies","B":"IAM Access Analyzer policy validation — checks policy syntax, AWS best practices, and security warnings before deployment","C":"IAM Policy Simulator — simulates API calls against existing attached policies","D":"AWS Config IAM policy evaluation rule — evaluates policies after resource creation"},"correct":"B","explanation":"IAM Access Analyzer includes a Policy Validation feature that checks IAM policies (identity-based, resource-based, SCPs) before deployment. It identifies: (1) Errors — syntax mistakes, invalid action names. (2) Warnings — overly permissive actions (e.g., 's3:*' instead of specific actions). (3) Security findings — policies that grant public access. (4) Suggestions — best practice improvements. This is available via the IAM console, AWS CLI (\`aws accessanalyzer validate-policy\`), and integrates into CI/CD pipelines for policy-as-code workflows.","distractors":{"A":"IAM Access Analyzer external access analysis examines already-deployed resource policies in your account to find external sharing — it is reactive (after deployment), not proactive (before deployment).","C":"IAM Policy Simulator tests specific API actions against policies already attached to a user, group, or role — it does not validate policy documents for errors or generate security warnings, and requires policies to already be attached.","D":"AWS Config evaluates resource configurations after they are created and deployed — it cannot validate a policy document before deployment."},"source_url":"https://docs.aws.amazon.com/IAM/latest/UserGuide/access-analyzer-policy-validation.html","tags":["iam-access-analyzer","policy-validation","pre-deployment","iac","security"],"verified":true}]`);export{e as default};